import logging
from ute_common_abstract_core import logger as core_logging


def debug_level_or_info_level():
    """return debugging level is set, else INFO level"""
    if core_logging.debug_level is not None:
        level = core_logging.debug_level
    else:
        level = logging.INFO
    return level


def configure_main_logger():
    """Configure main logger """
    core_logging.create_logger(name='ta_measurements', log_file='ta_measurements.log',
                               log_level=logging.DEBUG,
                               log_format='%(asctime)s | %(name)-35s | %(levelname)-8s | %(threadName)-23s | '
                                          '%(message)s /// %(funcName)s::%(filename)s(%(lineno)d)')
    logger = logging.getLogger('ta_measurements')
    logger.propagate = False
